INSERT INTO `achievements` VALUES ('Kec Conference and Journal','<p><span style=\"color: rgb(0, 0, 0);\">Served as a key member of the </span><strong style=\"color: rgb(0, 0, 0);\">KEC Conference and Journal Editor Committee</strong><span style=\"color: rgb(0, 0, 0);\">, contributing in multiple roles including </span><strong style=\"color: rgb(0, 0, 0);\">IT Head, Organizer, Reviewer, and Manager</strong><span style=\"color: rgb(0, 0, 0);\"> for KEC Conference 2021, 2022, and 2025 (2082). Managed technical and IT-related operations, supported conference planning and execution, reviewed research papers for technical quality and relevance, and coordinated academic and operational activities to ensure the successful organization of the conferences. Contributed to maintaining research standards, improving event management processes, and supporting the overall success of KEC’s academic initiatives.</span></p>',NULL,1,NULL,'','2026-08-01 17:07:50','2327e20d-9367-4140-9928-5c7188d4','04558230-ffc2-44f4-8234-f4f065f8','ceb9f720-e8cf-49c5-b23e-6793bb7a'),('Face of College','<p><span style=\"color: rgb(0, 0, 0);\">Recognized as the </span><strong style=\"color: rgb(0, 0, 0);\">Face of the College</strong><span style=\"color: rgb(0, 0, 0);\"> and featured in the institution\'s official branding and promotional materials. Appeared on the </span><strong style=\"color: rgb(0, 0, 0);\">college calendar, campus banners, official posters, and digital marketing campaigns</strong><span style=\"color: rgb(0, 0, 0);\">, representing the college\'s academic excellence, innovation, and student achievements. Served as a student ambassador, promoting the institution through various print and digital media.</span></p>',NULL,1,NULL,'','2026-08-01 16:53:58','cbe19331-ce6d-4635-bd16-ca67a78a','cae0c3ae-4c6e-470f-828b-19c387ed','2c9e6734-0218-4077-b21f-a0fb8455'),('Best Project Winners','<h2><span style=\"color: rgb(0, 0, 0);\">Best Major &amp; Minor Project Winner</span></h2><p><span style=\"color: rgb(0, 0, 0);\">Awarded </span><strong style=\"color: rgb(0, 0, 0);\">Best Major Project</strong><span style=\"color: rgb(0, 0, 0);\"> and </span><strong style=\"color: rgb(0, 0, 0);\">Best Minor Project</strong><span style=\"color: rgb(0, 0, 0);\"> for developing innovative engineering solutions that demonstrated strong technical knowledge, practical implementation, and real-world impact.</span></p><h3><br></h3>',NULL,1,NULL,'','2026-08-01 16:28:03','da837d90-712b-40b6-b582-0f956a36','e8e1131c-b343-464b-a454-a0f0c0aa','a0374bb0-d73c-4fb8-a46a-b8acc967'),('Technical Exhibition Organizer & Judge ','<p><span style=\"color: rgb(0, 0, 0);\">Served as an </span><strong style=\"color: rgb(0, 0, 0);\">Organizer and Judge for KEC LITE 2081</strong><span style=\"color: rgb(0, 0, 0);\"> at Kantipur Engineering College, contributing to the planning, coordination, and successful execution of the technical exhibition. Managed technical activities, supported project demonstrations, evaluated innovative student projects as a judge, and collaborated with teams to ensure smooth event operations.</span></p>',NULL,1,NULL,'','2026-08-01 17:03:16','ef6845ea-33f3-4baa-a084-93fd7c84','f8e96413-afcc-4574-9a78-7773001c','fc148841-14de-4170-aeb3-dc291020');
