--
-- Table structure for table `entity_content_details`
--

DROP TABLE IF EXISTS `entity_content_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `entity_content_details` (
  `id` varchar(36) NOT NULL,
  `entity_content_id` varchar(36) NOT NULL,
  `image_id` varchar(36) DEFAULT NULL,
  `title` varchar(255) DEFAULT '',
  `embed_urls` text,
  `embedded_url` text,
  `display_order` int DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_entity_content` (`entity_content_id`),
