  CONSTRAINT `fk_ep_journey` FOREIGN KEY (`journey_id`) REFERENCES `journey` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
