INSERT INTO `entity_promotions` VALUES ('01da1b0c-ed4e-41de-bca5-2d66e72c','c2a5a6ee-001d-4c48-a73e-ee0e467f','2017-11-06',NULL,'2017-11-06','Internship','Completed an internship at Shree Airlines, gaining practical exposure to aircraft maintenance operations and technical documentation. Assisted in developing and maintaining technical records, organising and updating the technical library, and supporting production planning activities. Gained hands-on understanding of aircraft maintenance procedures, inspection processes, and supervision practices while working with engineering teams to ensure compliance with aviation standards and operational requirements.',0,'2026-07-29 09:20:04'),('033e0cec-bccf-489a-a8fb-05d55f25','de2bf4ae-4e3f-4b2a-a404-acbf01f1','2023-06-01',NULL,'2023-06-01','Guest Sr Lecturer','Served as a Guest Lecturer at Kathford Engineering College, delivering lectures on Filter Design, RF and Microwave Engineering, and Internet and Intranet. Provided academic guidance, shared practical knowledge, and supported students in understanding theoretical concepts and their engineering applications.',0,'2026-07-29 12:34:34'),('07af2004-beb1-49da-800c-992cbdd9','77ec1914-f076-4897-8af9-88325c15','2021-04-19','2011-10-22','2021-04-19','Promoted to Assitant Lecturer','Worked as an **Assistant Lecturer** for **Filter Design**, delivering lectures and conducting laboratory sessions for **Computer Network and Security, Distributed Systems,** and **Filter Design**. Supported students in practical learning and provided academic guidance during lab sessions.\n',1,'2026-08-01 16:50:30'),('145b15d6-f143-4afe-977f-c6d76adc','64b36d64-4049-45bc-921d-b49617a0','2018-06-01',NULL,'2018-06-01','Junior Telecom and Network Engineer','Worked as a VSAT Support Engineer under the VSAT and Radio Department, responsible for the installation, configuration, monitoring, and maintenance of satellite communication systems. Performed installation and maintenance of dish antennas, analysed Ku-band and C-band frequencies, monitored satellite carriers and signal spill-over, and configured new carrier wave links. Provided L2 support for client and hub-side operations, including routing and switching, bandwidth monitoring, firewall management, and network security maintenance. Gained hands-on experience in server virtualisation technologies including Red Hat Virtualisation, iDirect Guest OS, KVM virtualisation, Microsoft Hyper-V, and virtual machine deployment and management. Supported infrastructure operations through system monitoring, troubleshooting, and optimisation of satellite and network resources',0,'2026-07-29 09:22:49'),('1a2e940f-2680-4f70-8470-e8da23ad','77ec1914-f076-4897-8af9-88325c15','2019-11-18','2019-03-18','2019-11-18','Hired as Lab Assistant','Served as a **Lab Assistant** for **Computer Networks, Communication II, Data Communication, Filter Design,** and **C++ Programming**, assisting students during lab sessions, preparing lab exercises, maintaining laboratory equipment, and providing technical support for practical learning.\n',0,'2026-08-01 16:50:30'),('3f5317cb-ca34-4ee6-a3c1-0e014520','a8b04faa-d22b-493b-b020-aed5a592','2019-02-01','2019-06-30','2019-02-01','Quality Control Engineer ','Responsible for ensuring the quality and compliance of network, communication, and fire alarm system projects through effective design review, monitoring, and inspection. Experienced in designing and implementing internet and CCTV network infrastructure, conducting quality inspections, verifying system performance, and ensuring installations meet project specifications and industry standards. Skilled in monitoring project progress, identifying and resolving quality issues, preparing technical documentation and inspection reports, and coordinating with engineering and installation teams to deliver reliable, safe, and high-quality solutions.',0,'2026-07-29 09:33:54'),('648249c1-9e2e-49e9-a084-9e65362a','f8645475-ea63-48b3-984d-1504935d','2023-06-01',NULL,'2023-06-01','Senior Backend Developer','',0,'2026-07-29 12:52:00'),('68a7475e-53ff-433e-9299-f6d8bc3c','a8b04faa-d22b-493b-b020-aed5a592','2020-02-12','2020-07-05','2020-02-12','Consulting','specialising in the design and development of low-voltage electrical and ELV systems. Responsibilities included preparing CAD drawings, network and telecommunication designs, fire alarm system layouts, smart energy meter designs, smart energy meter network planning, electrical load calculations, and earthing system designs. Also involved in the design of DG systems, electrical panels, and single-line diagrams, along with providing technical consultancy and design support to clients and project teams. Coordinated with engineers and stakeholders to deliver accurate, efficient, and standards-compliant design solutions.',2,'2026-07-29 09:33:54'),('896fa81b-bd49-426e-a759-6f4aba40','c1246171-0b86-4f96-8f5f-f91ea488','2019-09-01','2023-05-31','2019-09-01','IT Engineer','Experienced in full-stack application development using **JavaScript**, building responsive client-side applications with **React** and developing scalable server-side solutions using **Node.js** and **Django**. Skilled in deploying and managing applications on cloud platforms, including **AWS** and **Alibaba Cloud**, while administering network servers and technology infrastructure. Proficient in automating the software development lifecycle through **CI/CD** pipelines, collaborating effectively with cross-functional teams, and developing **microservices-based** applications to deliver reliable and maintainable software solutions.\n',0,'2026-07-29 09:35:43'),('a5de3dce-3164-4cbf-8284-06403e1f','77ec1914-f076-4897-8af9-88325c15','2024-11-03',NULL,'2024-11-03','Senior Lecturer','Served as a **Senior Lecturer**, delivering lectures on **Filter Design, RF and Microwave Engineering,** and **Internet and Intranet**. Developed course materials, assignments, and assessments while applying modern teaching methods to enhance student learning. Supervised laboratory sessions for **Microprocessor, Internet and Intranet, RF and Microwave Engineering,** and **Embedded Systems**, providing practical guidance and technical support. Mentored students in final-year projects and technical exhibitions, supporting project development, research, and innovation. Contributed to academic research, curriculum improvement, departmental activities, and academic administration.',3,'2026-08-01 16:50:30'),('b7478010-225b-4f64-99f4-8f1108da','77ec1914-f076-4897-8af9-88325c15','2021-10-23','2024-11-02','2021-10-23','Lecturer','Promoted to **Full-Time Lecturer** in recognition of dedication, teaching performance, and academic contribution. Responsible for delivering lectures on **Filter Design, RF and Microwave Engineering,** and **Internet and Intranet**. Supervised laboratory sessions for **Microprocessor, Internet and Intranet,** and **RF and Microwave Engineering**, providing students with practical guidance and technical support. Actively contributed to KEC activities, including **KEC Lite 2023**, served as a **Member of the KEC Conference Organizing Committee (2021 & 2022)**, and authored **two research papers published in the KEC Conference (2022)**.',2,'2026-08-01 16:50:30'),('d76b7a6b-bf6d-4421-82be-d06948f3','a8b04faa-d22b-493b-b020-aed5a592','2019-02-11','2019-07-30','2019-02-11','Low voltage system design','Worked as a **Low Voltage Designer** at **Techno Chat Pvt. Ltd.**, specialising in the design of low-voltage electrical and ELV systems. Responsibilities included preparing CAD drawings, performing electrical load calculations, designing network and telecommunication systems, developing fire alarm system layouts, and planning smart energy meter networks. Also involved in the design of diesel generator (DG) systems, electrical panels, and single-line diagrams while coordinating with engineers and project teams to deliver accurate, standards-compliant designs.\n',1,'2026-07-29 09:33:54');
