DROP TABLE IF EXISTS `journey`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `journey` (
  `title` varchar(255) NOT NULL,
  `office_name` varchar(255) NOT NULL,
  `designation` varchar(255) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `description` text,
  `contents` text,
  `url_of_company` varchar(500) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `id` varchar(36) NOT NULL,
  `background_document_id` varchar(36) DEFAULT NULL,
  `document_id` varchar(36) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_journey_bg_document` (`background_document_id`),
  KEY `fk_journey_document` (`document_id`),
  CONSTRAINT `fk_journey_bg_document` FOREIGN KEY (`background_document_id`) REFERENCES `documents` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_journey_document` FOREIGN KEY (`document_id`) REFERENCES `documents` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
