INSERT INTO `journey` VALUES ('Network and System Engineer','Mercantile telecommunication','Junior Telecom and Network Engineer','2018-06-01',NULL,'<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Routing and Switching</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Server Virtualization (Red Hat o/s and IDirect Guest o/s)</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Monitoring and management of overall satellite bandwidth</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">L2 Support and maintenance of both client and hub side</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Monitoring of overall satellite carrier and spill over</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Installation and configuration of new carrier wave</span></li></ol><p><br></p>',NULL,NULL,'2026-07-28 13:59:47','2026-07-29 09:22:49','64b36d64-4049-45bc-921d-b49617a0','8ea11cd4-1a67-4839-a55a-2eb591d4','3a6e5cdf-4e03-4e80-bbbf-22a8c81a'),('Academic Journey','Kantipur Engineering College','Senior Lecturer','2019-11-18',NULL,'<p><span style=\"color: rgb(0, 0, 0);\">Progressed from </span><strong style=\"color: rgb(0, 0, 0);\">Lab Assistant</strong><span style=\"color: rgb(0, 0, 0);\"> to </span><strong style=\"color: rgb(0, 0, 0);\">Senior Lecturer</strong><span style=\"color: rgb(0, 0, 0);\"> at Kantipur Engineering College, delivering courses in Filter Design, RF and Microwave Engineering, Internet and Intranet, and Computer Networks. Conducted laboratory sessions, developed course materials, supervised final-year projects, mentored students in technical exhibitions, and contributed to research and academic development.</span></p><p><br></p>',NULL,NULL,'2026-07-29 09:02:12','2026-08-01 16:50:30','77ec1914-f076-4897-8af9-88325c15','d91ff558-f247-4492-93c6-06967b96','781c8791-23cb-449b-a508-66c9d13d'),('Low Voltage Quality Control Engineer ','Free Lancing ','Low voltage system design','2019-02-01','2019-07-30','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Designing and Monitoring:</span></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Network and communication:</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Fire alarm System:</span></li></ol><p><br></p>',NULL,NULL,'2026-07-28 21:21:51','2026-07-29 09:33:54','a8b04faa-d22b-493b-b020-aed5a592','f836152c-7a81-4a8f-80be-efaefc78','24c2d702-10fe-435d-8a1c-00ec1003'),('React Developer and DevOps','ItConcerns','IT Engineer','2019-09-01','2023-05-31','<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">JavaScript Application Development on both client (React) and server-side (Node, Django)</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Working on cloud technologies such as AWS and Alibaba</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Manage network servers and technology tools</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Automation of the software development lifecycle.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Collaboration, Communication, CI/CD, Microservices</span></li></ol><p><br></p>',NULL,NULL,'2026-07-29 08:51:02','2026-07-29 09:35:43','c1246171-0b86-4f96-8f5f-f91ea488','1fd96d38-101a-4bd1-8883-d7ed7487','11bf42b8-cc79-40e7-99d5-d5341c75'),('Aircraft Maintenance Engineer Internship','Shree Airlines','Internship','2017-11-06',NULL,'<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Developing Technical Records.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Developing Technical Library.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Developing Production planning.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Aircraft maintenance and supervision</span></li></ol><p><br></p>',NULL,NULL,'2026-07-28 13:38:04','2026-07-29 09:20:04','c2a5a6ee-001d-4c48-a73e-ee0e467f','aad7a655-5d78-4a4c-be53-033d9bee','e4054017-750a-4eec-ab65-13797b63'),('Part time Lecturer(Present Kathford)','Kathford: Engineering and Management College','Guest Sr Lecturer','2023-06-01',NULL,'<p><strong style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\"><u>Kathford Engineering College (June 2023 to Present)</u></strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\"><em><u>Lecturer for subject</u></em></strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\">“Filter Design”,</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\">“Rf and Microwave Engineering” and</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\">“Internet and Intranet(KEC Only)”</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\"><em><u>Lab Works on Subject such as</u></em></strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\">“Microprocessor”,</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\">“Internet and Intranet”,</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\">“Rf and Microwave Engineering,</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0); background-color: rgb(255, 255, 255);\">“Embedded System”</span></li></ol><p><br></p>',NULL,NULL,'2026-07-29 12:34:34','2026-07-29 12:34:34','de2bf4ae-4e3f-4b2a-a404-acbf01f1',NULL,'305af7e2-67de-4d76-9b89-37195b60'),('Freelancing Full Stack Developer','Nerd Study Hub','Senior Backend Developer','2023-06-01',NULL,'<p><span style=\"color: rgb(0, 0, 0);\">Experienced </span><strong style=\"color: rgb(0, 0, 0);\">Full Stack Developer</strong><span style=\"color: rgb(0, 0, 0);\"> with expertise in designing, developing, deploying, and maintaining scalable web and desktop applications using modern technologies. Worked on diverse projects including healthcare platforms, mobile applications, municipal management systems, and enterprise solutions for international and local clients. Skilled in frontend development using </span><strong style=\"color: rgb(0, 0, 0);\">React, Next.js, Remix, React Native, Electron, and Tailwind CSS</strong><span style=\"color: rgb(0, 0, 0);\">, along with backend development using </span><strong style=\"color: rgb(0, 0, 0);\">Node.js, Express, FastAPI, and RESTful API architectures</strong><span style=\"color: rgb(0, 0, 0);\">.</span></p><p><span style=\"color: rgb(0, 0, 0);\">Experienced in database design and management using </span><strong style=\"color: rgb(0, 0, 0);\">PostgreSQL, Sequelize, SQLAlchemy, and Alembic</strong><span style=\"color: rgb(0, 0, 0);\">, including schema design, migrations, and query optimisation. Implemented secure authentication and authorization systems, optimized application performance through code splitting and efficient architecture, and developed cross-platform applications with responsive user interfaces.</span></p><p><span style=\"color: rgb(0, 0, 0);\">Hands-on experience with </span><strong style=\"color: rgb(0, 0, 0);\">cloud deployment and DevOps practices</strong><span style=\"color: rgb(0, 0, 0);\">, including hosting applications on </span><strong style=\"color: rgb(0, 0, 0);\">DigitalOcean and AWS EC2</strong><span style=\"color: rgb(0, 0, 0);\">, server management, Samba-based file sharing, </span><strong style=\"color: rgb(0, 0, 0);\">Jenkins CI/CD pipeline integration</strong><span style=\"color: rgb(0, 0, 0);\">, and </span><strong style=\"color: rgb(0, 0, 0);\">Grafana monitoring and logging</strong><span style=\"color: rgb(0, 0, 0);\">. Skilled in troubleshooting, system optimization, API integration, and delivering reliable software solutions while collaborating with cross-functional teams.</span></p><p><br></p>',NULL,NULL,'2026-07-29 12:46:55','2026-07-29 12:52:00','f8645475-ea63-48b3-984d-1504935d','16cfa3e7-8dc7-4ba2-98c5-127736b7','9d863348-5419-4e5d-941b-d202c39a');
