INSERT INTO `projects` VALUES ('Bank Management System – C++','academicsproject','<h1><span style=\"background-color: oklch(0.928 0.006 264.531); color: rgb(0, 0, 0);\">The topic for our project is \'Bank Management System\'. File handling has been effectively used for each feature of this project. Our Bank Management System can add records, search, modify &amp; delete records. General concepts of if while loops, functions, classes and file has been used to create this program.</span></h1>','<h1><strong style=\"color: rgb(0, 0, 0);\">Bank Management System</strong><span style=\"color: rgb(0, 0, 0);\"> is a console-based application developed in </span><strong style=\"color: rgb(0, 0, 0);\">C++</strong><span style=\"color: rgb(0, 0, 0);\"> that simulates basic banking operations using </span><strong style=\"color: rgb(0, 0, 0);\">file handling</strong><span style=\"color: rgb(0, 0, 0);\"> for persistent data storage. The project was designed to demonstrate core object-oriented programming concepts and file management techniques by allowing users to manage customer bank records efficiently.</span></h1><h2><span style=\"color: rgb(0, 0, 0);\">Key Features</span></h2><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Create and store new customer accounts</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Search customer records using account details</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Modify existing customer information</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Delete customer records</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Persistent data storage using file handling</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Menu-driven interface for easy navigation</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Efficient record management with basic validation</span></li></ol><h2><span style=\"color: rgb(0, 0, 0);\">Technologies Used</span></h2><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">C++</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Object-Oriented Programming (Classes &amp; Objects)</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">File Handling</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Functions</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Conditional Statements and Loops</span></li></ol><h2><span style=\"color: rgb(0, 0, 0);\">Learning Outcomes</span></h2><p><span style=\"color: rgb(0, 0, 0);\">This project enhanced my understanding of object-oriented programming, file handling, and data management in C++. It provided practical experience in implementing CRUD (Create, Read, Update, Delete) operations, designing menu-driven applications, and organizing code using classes, functions, loops, and conditional statements while working with persistent data storage.</span></p>',NULL,1,NULL,NULL,NULL,'2026-08-01 14:51:33','1eb9d192-d11a-45c6-8f72-3cb02380',NULL),('Smart Health Ward','workproject','<p>Ward3 Lab report Management System (Application made for lalitpur Ward 3)</p>','<p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">WardBackend</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">:</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The WardBackend project is a Node.js-based backend application developed using TypeScript, designed to support the functionalities of the WardHealth system. It integrates popular libraries and frameworks such as Express.js for building the server, Sequelize for ORM functionality with PostgreSQL, and Multer for handling file uploads. The backend offers functionality for </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">report generation</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">, allowing users to create, store, and view reports dynamically. These reports can be formatted for print, providing flexibility to export data in printable formats. The project also includes RESTful API endpoints for generating and managing these reports. Additionally, the backend supports modern development tools like ESLint for linting, Prettier for code formatting, and Jest for testing. Nodemon is used for live reloading during development, and TypeScript ensures type safety across the codebase.</span></p><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">WardHealth-UI-Type</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">:</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">WardHealth-UI-Type is a React-based front-end application for the WardHealth system, utilizing Material-UI components and Redux for state management. The UI is built with a focus on a responsive and modern experience, featuring </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">report viewing</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> and </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">report generation</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> functionalities. Users can access and view detailed reports within the interface, with the option to export these reports in formats suitable for printing. Material-UI is used to ensure a sleek, professional design while libraries like Formik handle form validation and React-Query manages data fetching efficiently. TypeScript provides type safety across the project. Additionally, the project integrates tools for testing like React Testing Library and Jest. CRACO is used for configuring Create React App to allow custom setups.</span></p><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Together, </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">WardBackend</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> and </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">WardHealth-UI-Type</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> aim to provide a comprehensive solution for the WardHealth platform, enabling users to easily generate, view, and print reports, while maintaining robust backend functionality for data management and API services.</span></p><p><br></p>',NULL,1,NULL,NULL,'0b584e6e-5586-4ae8-9dee-f0eb0dfd','2026-08-01 13:50:09','3e1035d4-4914-41b0-bed1-3919c190',NULL),('Basic Ecommerce site ','workproject','<p>For Anapple construction to sell thier chemical product, Startup Store to sell Hats, Shoes and so-on</p>','<h3><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Anapple Construction - Chemical Products:</span></h3><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Anapple Construction</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> is your trusted partner for high-quality chemical products designed for the construction industry. From advanced adhesives and sealants to protective coatings, we offer a wide range of specialty chemicals that meet the toughest standards for durability and performance. Whether you’re working on a large-scale project or small repairs, our products ensure long-lasting results, reliability, and efficiency. Let Anapple Construction provide you with the chemical solutions you need to build with confidence.</span></p><h3><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Startup Store - Hats, Shoes, and More:</span></h3><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Startup Store</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> is your go-to destination for the latest in fashion and style! Whether you’re looking for the perfect hat to top off your outfit, a new pair of shoes to walk the streets in, or a variety of other trendy accessories, we’ve got you covered. Our curated collection of stylish, high-quality products is designed to fit every occasion, from casual to chic. Explore our selection today and step into a world of fashion-forward finds at unbeatable prices. At Startup Store, we make it easy to shop for the latest trends that suit your personal style!</span></p><p><br></p>','http://localhost:8000/uploads/projects/2026/08/20260801073150_paste-1785569493625.png',1,NULL,NULL,'9ca6598f-d0ac-4636-8b21-27692b09','2026-08-01 12:56:46','44513486-14da-4092-b385-13ba0ec0','9351a203-7ac5-43af-b7a3-44ba2936'),('Bio Robotic Arm','academicsproject','<p><span style=\"background-color: oklch(0.928 0.006 264.531); color: rgb(0, 0, 0);\">“Bio-Robotic arm” is project based on a biofeedback mechanical arm that uses a low dimensional input derived from EMG (electromyography) data.</span></p>','<p><strong style=\"color: rgb(0, 0, 0);\">Bio-Robotic Arm</strong><span style=\"color: rgb(0, 0, 0);\"> is a biomedical engineering project that demonstrates the control of a robotic arm using </span><strong style=\"color: rgb(0, 0, 0);\">Electromyography (EMG)</strong><span style=\"color: rgb(0, 0, 0);\"> signals. The system captures biofeedback from muscle activity and converts these signals into movements of a mechanical arm, enabling intuitive human-machine interaction. The project showcases the practical application of biomedical signal processing and embedded systems in assistive robotics.</span></p><h2><span style=\"color: rgb(0, 0, 0);\">Key Features</span></h2><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">EMG-based control of a robotic arm using muscle signals</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Biofeedback mechanism for real-time movement detection</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Low-dimensional signal processing for efficient control</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Real-time response between muscle activity and robotic arm movement</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Demonstrates human-machine interaction through biological signals</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Potential applications in prosthetics, rehabilitation, and assistive technologies</span></li></ol><h2><span style=\"color: rgb(0, 0, 0);\">Technologies Used</span></h2><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Electromyography (EMG) Sensor</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Microcontroller (Arduino/Embedded System)</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Servo Motors</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">C/C++ Programming</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Biomedical Signal Processing</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Electronic Circuits</span></li></ol><h2><span style=\"color: rgb(0, 0, 0);\">Learning Outcomes</span></h2><p><span style=\"color: rgb(0, 0, 0);\">This project provided hands-on experience in biomedical engineering, embedded systems, and robotics. It strengthened my understanding of EMG signal acquisition, biofeedback systems, sensor integration, motor control, and real-time embedded programming while demonstrating how biological signals can be used to control robotic devices for healthcare and assistive applications.</span></p><p><br></p>','http://localhost:8000/uploads/projects/2026/08/20260801090945_paste-1785575318325.png',1,NULL,NULL,NULL,'2026-08-01 14:54:45','57b46cdc-df70-4178-bb1c-9d709069','f73f6c1f-6bb1-4714-9103-1939929e'),('Paige: Diet Coaching Applications','workproject','<p>An Israel based Full Stack Development Application using react(Formik, reduxtoolkit, joy, materialUI, styledComponents) and Node(Express, Sequalize, Postgres) and Hybrid App development using React Native</p>','<p><strong>Paige</strong> is a comprehensive diet coaching app designed specifically for users in Israel, offering personalized diet plans, fitness tracking, and real-time communication with diet coaches. The app is available on both <strong>iOS</strong> and <strong>Android</strong>, ensuring that users can access their diet plans, track their progress, and stay motivated on the go. The frontend is developed using <strong>React Native</strong>, and the backend utilizes <strong>Node.js</strong> and <strong>PostgreSQL</strong> to deliver a robust, scalable solution.</p><h3><strong>Frontend (React Native - iOS &amp; Android)</strong></h3><p>The <strong>Frontend</strong> of <strong>Paige</strong> is built using <strong>React Native</strong>, enabling a seamless experience across both <strong>iOS</strong> and <strong>Android</strong>platforms. This cross-platform approach ensures that users can easily access personalized nutrition advice, track their progress, and engage with their diet coaches no matter their device.</p><h4>Key Features:</h4><ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>User Interface</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>The app has a clean and intuitive UI, built with <strong>React Native Paper</strong> and <strong>React Native Elements</strong> to provide a consistent, responsive design. Components are optimized for both iOS and Android devices, ensuring an engaging user experience.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Personalized Diet Plans</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Users receive customized diet and workout plans tailored to their goals and preferences, leveraging dynamic forms built with <strong>Formik</strong> for easy user interaction and data input.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Notification System</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Notifee</strong> powers the app’s notification system, sending real-time reminders and updates directly to the user\'s phone. Additionally, <strong>Firebase Cloud Messaging</strong> is integrated to send push notifications, helping users stay on track with their diet and fitness routines.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Real-Time Communication</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Socket.IO</strong> is used for real-time communication between the users and their diet coaches. This enables users to ask questions and receive support instantly.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Form Management</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Formik</strong> simplifies form handling for user sign-up, diet plan submissions, and other interactions. <strong>Yup</strong> is integrated for form validation to ensure the accuracy of user input.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Progress Tracking</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Users can log their meals, track calories, and visualize their progress through charts powered by <strong>Victory Native</strong> and <strong>react-native-chart-kit</strong>. This allows for a detailed analysis of diet and fitness goals.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Cross-Platform Support</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>The app is built to run smoothly on both <strong>iOS</strong> and <strong>Android</strong> platforms using <strong>React Native</strong>, providing a consistent experience across devices.</li></ol><h4>Key Technologies:</h4><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>React Native</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>React Navigation</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Formik</strong> &amp; <strong>Yup</strong> for form management</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Notifee</strong> &amp; <strong>Firebase Cloud Messaging</strong> for notifications</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Socket.IO</strong> for real-time communication</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Victory Native</strong> and <strong>react-native-chart-kit</strong> for progress tracking</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>React Native Paper</strong> and <strong>React Native Elements</strong> for UI components</li></ol><h3><strong>Backend (Node.js, PostgreSQL, Sequelize)</strong></h3><p>The <strong>Backend</strong> of <strong>Paige</strong> is powered by <strong>Node.js</strong>, utilizing <strong>Express.js</strong> for the API layer, <strong>PostgreSQL</strong> for the database, and <strong>Sequelize ORM</strong> to manage database interactions. The backend is designed to handle user data, diet plans, progress tracking, authentication, and more, ensuring a smooth and secure experience for users.</p><h4>Key Features:</h4><ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>User Authentication</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>The backend employs <strong>JWT authentication</strong> for secure user login and registration, ensuring that users\' data is protected at all times.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Diet Plan Management</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>The backend manages users\' personalized diet plans and fitness schedules. Using <strong>Sequelize</strong>, it connects to the <strong>PostgreSQL</strong> database to store and retrieve data efficiently.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Real-Time Communication</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Socket.IO</strong> is integrated into the backend to enable real-time communication between users and diet coaches. This allows users to ask questions and get immediate responses.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Database Management</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>PostgreSQL</strong> is used as the database to store all the app’s critical data, such as user profiles, diet plans, and progress. <strong>Sequelize ORM</strong> is used to manage database operations, allowing for efficient querying and data manipulation.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Push Notifications</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Firebase Admin SDK</strong> is used on the backend to send notifications to users\' mobile devices. This allows for personalized alerts, reminders, and updates.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Testing &amp; Development</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>The backend includes several testing scripts, ensuring that the app functions correctly in different environments. The <strong>Sequelize CLI</strong> is used for database migrations, while <strong>Jest</strong> is employed for unit testing.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Security</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>The app uses <strong>bcryptjs</strong> for hashing user passwords and <strong>Express JWT</strong> for secure token-based authentication, ensuring data security.</li></ol><h4>Key Technologies:</h4><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Node.js</strong> with <strong>Express.js</strong></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>PostgreSQL</strong> for the database</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Sequelize</strong> ORM for data management</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>JWT Authentication</strong> for secure login</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Socket.IO</strong> for real-time communication</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Firebase Admin SDK</strong> for notifications</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Jest</strong> and <strong>Supertest</strong> for testing</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Sequelize CLI</strong> for database migrations</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Bcryptjs</strong> for password hashing</li></ol><h3><strong>Paige App Deployment</strong>:</h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>React Native App</strong>:</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Google Play Store</strong>: <u style=\"color: rgb(0, 102, 204);\"><a href=\"https://play.google.com/store/apps/details?id=com.paigemob&amp;hl=en\" rel=\"noopener noreferrer\" target=\"_blank\">Paige App on Play Store</a></u></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Apple App Store</strong>: <u style=\"color: rgb(0, 102, 204);\"><a href=\"https://apps.apple.com/us/app/paige-the-last-food-fight/id6469138670\" rel=\"noopener noreferrer\" target=\"_blank\">Paige App on App Store</a></u></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Web Login Portal</strong>: <u style=\"color: rgb(0, 102, 204);\"><a href=\"https://paigeapp.com/login\" rel=\"noopener noreferrer\" target=\"_blank\">Paige App Login</a></u></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Backend API</strong>:</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>The backend API is hosted and served through a <strong>Node.js</strong> server with <strong>PostgreSQL</strong> as the database. It is responsible for managing user data, diet plans, notifications, and real-time communication.</li></ol><p><br></p>','/uploads/projects/2026/08/20260801075818_paste-1785570877613.png',1,NULL,NULL,'92713dbf-87e4-49dc-af7d-16f356d4','2026-08-01 13:43:18','7e0a7a45-5cda-49e7-b04c-b4ecf6c3','543db3bb-ab10-4dbe-9542-3c89144f'),('Amazon Clone','workproject','<p>An Amazon clone built with React, Redux, and Firebase. It allows users to browse products, add them to their cart, and make secure purchases. The app utilizes Redux for state management and Firebase for user authentication and real-time database functionality, providing a smooth and dynamic shopping experience.</p>','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">This </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Amazon Clone</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> is a full-featured e-commerce application built using </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">React</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">, </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Redux</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">, and </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Firebase</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">. Here’s a breakdown of the core technologies and features used:</span></p><h3><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Key Technologies:</strong></h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">React</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: The user interface is built with React, offering a component-based structure that ensures a responsive and dynamic experience. React\'s virtual DOM makes the app efficient by minimizing re-rendering.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Redux</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Redux is used for global state management. It helps maintain a centralized state for the app, such as the user\'s cart, authentication status, and product list, making it easy to manage state across different components.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Firebase</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Firebase is used for two key functionalities:</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Authentication</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Firebase Authentication is integrated to handle user login and registration securely, supporting various methods like email/password and Google sign-in.</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Real-Time Database</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Firebase’s real-time database stores product information, cart data, and order history, ensuring users see up-to-date information without needing to refresh the page.</span></li></ol><h3><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Features:</strong></h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">User Authentication</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Users can create an account or sign in using Firebase Authentication. Once logged in, users can access their cart and order history.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Product Listing</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: A dynamic list of products, pulled from Firebase, is displayed on the homepage. Users can filter and search through products to find items that interest them.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Product Details</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Each product has a detailed page with information like description, price, and images. Users can add items to their cart from this page.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Shopping Cart</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Redux is used to manage the cart\'s state, allowing users to add, remove, or update quantities of items. The cart is persistent, even if the user logs out and logs back in.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Secure Checkout</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: The app integrates a secure checkout flow, where users can proceed to payment after reviewing their cart. (Note: This part may be simulated in a clone for development purposes, as it typically requires payment gateway integration like Stripe).</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Real-Time Updates</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Using Firebase’s real-time database, any updates to product availability, pricing, or inventory are reflected instantly without needing a page reload.</span></li></ol><p><br></p>','http://localhost:8000/uploads/projects/2026/08/20260801073819_paste-1785569682959.png',1,NULL,NULL,'573f696e-f521-4e0b-b001-0f8c1cae','2026-08-01 13:23:19','7e63dbdb-2120-4af9-95cd-e5aa3faa','307f0824-b64f-45e4-9ab0-69217a0c'),('Covid Tracker','workproject','<p>Covid Tracker to track ongoing cases during Covid-19</p>','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">This </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Covid Tracker</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> is a web application designed to track the ongoing cases of COVID-19 globally, with a focus on real-time data updates and user-friendly visualization. Here\'s a detailed description of the features and technology used in your project:</span></p><h3><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Key Features:</strong></h3><ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Track COVID-19 Cases:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The app provides a live feed of global COVID-19 cases, including active cases, recovered cases, and deaths. Users can check the status of different countries or regions and get the most up-to-date numbers.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">API Integration:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The app demonstrates how to handle API requests, utilizing reliable COVID-19 data sources like </span><u style=\"background-color: rgb(255, 255, 255); color: rgb(0, 102, 204);\"><a href=\"https://covid19api.com/\" rel=\"noopener noreferrer\" target=\"_blank\">COVID-19 API</a></u><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> or </span><u style=\"background-color: rgb(255, 255, 255); color: rgb(0, 102, 204);\"><a href=\"https://disease.sh/\" rel=\"noopener noreferrer\" target=\"_blank\">Disease.sh API</a></u><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">. The app makes requests to these APIs to fetch live data about cases, recoveries, and deaths, which is updated frequently.</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Handling API Requests:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> It shows how to fetch data asynchronously using JavaScript\'s fetch() or axiosand how to manage loading states and errors during data fetching.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Pinpoint Cases on the Map:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">An interactive map is integrated to pinpoint locations where COVID-19 cases have been reported. The map visualizes data by marking areas of active cases, providing users with a clearer understanding of how the virus has spread geographically.</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Popular mapping libraries like </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Leaflet</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> or </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Google Maps</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> API can be used to plot the data points dynamically based on the API responses.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Daily Info on Recovery, Cases, and Deaths:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Users can view daily statistics, including the number of new cases, recoveries, and deaths, allowing them to track the pandemic’s daily progress in different regions.</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">This information is crucial for users who want to see the day-to-day trends in COVID-19 data and monitor regions of concern.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">User-Friendly Dashboard:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The app has a clean and easy-to-use dashboard that updates in real-time with new data. It can feature sections for global statistics, country-specific data, and a map to visualize the spread of the virus.</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">A responsive design ensures that the app is accessible on both desktop and mobile devices, providing a seamless experience.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Data Filters &amp; Search Functionality:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Users can search for specific countries or regions to view their current COVID-19 statistics. Filters can be implemented to sort data by regions with the highest or lowest case counts.</span></li></ol><h3><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Technology Stack:</strong></h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">React:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> The front-end framework, used to build the app’s UI components and manage state.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Axios/Fetch:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> For making API requests to get real-time data about COVID-19 cases.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Leaflet/Google Maps API:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> To integrate an interactive map where users can see the geographical distribution of cases.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">CSS/Styled Components:</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> To make the UI visually appealing and responsive across devices.</span></li></ol><h3><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">How it Works:</strong></h3><ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The app fetches data from the COVID-19 API at regular intervals (e.g., every few seconds or minutes) to ensure the information is up-to-date.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The API provides data on cases, recoveries, deaths, and sometimes vaccination statistics, which is then displayed in a structured format.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The map updates as new data comes in, and it visually represents the locations with markers, potentially showing the severity of the cases using color-coded icons.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The app also has the capability to display daily updates, helping users to track trends over time and compare the current day’s data with past numbers.</span></li></ol><h3><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Additional Features (Optional Enhancements):</strong></h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Graphs/Charts</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Display data in graphical form, showing trends of new cases, recoveries, and deaths over time. This can be done using libraries like </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Chart.js</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> or </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Recharts</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Notifications/Alerts</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Users can subscribe to notifications for updates on a specific region\'s case count.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">News Updates</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Integrating a section for daily or weekly news on COVID-19 could enhance the app, making it a more comprehensive COVID-19 tracker.</span></li></ol><p><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">This app serves as a great tool for users to stay informed about the ongoing pandemic, and it demonstrates key concepts like API data handling, interactive maps, and displaying real-time information effectively.</span></p><p><br></p>','http://localhost:8000/uploads/projects/2026/08/20260801074959_paste-1785570532531.png',1,NULL,NULL,'b3c58436-1411-4cda-87bb-bc82b9ca','2026-08-01 13:34:59','89297556-b96d-4003-8581-4c174162','3f60dff1-3e65-4e98-8257-d3f78cd6'),('Thesis: SDN Load Balancing and DDoS Detection','academicsproject','<p><span style=\"background-color: oklch(0.928 0.006 264.531); color: rgb(0, 0, 0);\">This prject reduces the overhead in traffic, classify between traffic and DDoS Attack using SVM, find optimal path using DFS</span></p>','<p><strong style=\"color: rgb(0, 0, 0);\">SDN Load Balancing and DDoS Detection</strong><span style=\"color: rgb(0, 0, 0);\"> is a research-based thesis project that leverages </span><strong style=\"color: rgb(0, 0, 0);\">Software-Defined Networking (SDN)</strong><span style=\"color: rgb(0, 0, 0);\"> to optimize network performance while enhancing security against Distributed Denial-of-Service (DDoS) attacks. The system classifies normal and malicious network traffic using a </span><strong style=\"color: rgb(0, 0, 0);\">Support Vector Machine (SVM)</strong><span style=\"color: rgb(0, 0, 0);\">model and identifies optimal routing paths using the </span><strong style=\"color: rgb(0, 0, 0);\">Depth-First Search (DFS)</strong><span style=\"color: rgb(0, 0, 0);\"> algorithm to reduce network congestion and improve traffic distribution.</span></p><h2><span style=\"color: rgb(0, 0, 0);\">Key Features</span></h2><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Intelligent traffic classification using Support Vector Machine (SVM)</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Detection of DDoS attacks through machine learning techniques</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">SDN-based dynamic load balancing for efficient traffic management</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Optimal path selection using the Depth-First Search (DFS) algorithm</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Reduced network congestion and routing overhead</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Improved network performance, availability, and security</span></li></ol><h2><span style=\"color: rgb(0, 0, 0);\">Technologies Used</span></h2><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Software-Defined Networking (SDN)</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Python</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Support Vector Machine (SVM)</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">OpenFlow / SDN Controller</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Depth-First Search (DFS)</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Machine Learning</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Network Traffic Analysis</span></li></ol><h2><span style=\"color: rgb(0, 0, 0);\">Learning Outcomes</span></h2><p><span style=\"color: rgb(0, 0, 0);\">This thesis strengthened my knowledge of software-defined networking, machine learning, and network security. It provided practical experience in traffic analysis, DDoS detection, intelligent routing algorithms, and SDN architecture, demonstrating how machine learning and dynamic routing can be combined to build more secure and efficient computer networks.</span></p><p><br></p>','/uploads/projects/2026/08/20260801091103_paste-1785575461211.png',1,NULL,NULL,NULL,'2026-08-01 14:56:03','8d853fa4-27e8-4148-88e9-6c76bffc','de9cecb5-5971-4f7d-9366-0e1bd5b2'),('Inventory Management Application','workproject','<p>Inventory Management Application to track goods and supplies</p>','<p>The <strong>Inventory Management Application for Sanjog Suppliers</strong> is designed to streamline the management of stock, orders, and suppliers, ensuring that the supply chain operates smoothly and efficiently. The app provides tools to track inventory levels, monitor product performance, manage suppliers, and generate reports. Here’s a detailed description of the features and technologies used in the application:</p><h3><strong>Key Features:</strong></h3><ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Inventory Tracking:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>The app allows the user to track inventory levels in real-time. Each product has detailed information, including quantity, price, supplier, and reorder level.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Stock Management</strong>: Automatically updates inventory when stock is added, removed, or sold, and alerts the user when stock is running low.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Barcode Scanning</strong>: Integrate barcode scanning functionality for easy inventory updates. This can help in adding products or updating quantities by scanning product barcodes.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Product Management:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Product Addition and Editing</strong>: Admin users can add new products to the inventory or update existing product details, such as price, description, and quantity.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Categories &amp; Tags</strong>: Group products into categories (e.g., electronics, furniture, raw materials) and add tags for easier searching and filtering.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Product Search</strong>: A search functionality for quick product lookup based on product name, category, or supplier.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Supplier Management:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Supplier Profiles</strong>: Maintain detailed records of suppliers, including contact information, product list, and payment terms.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Order Management</strong>: Create and track orders to suppliers for restocking. The app helps in managing the order status (pending, shipped, received), along with expected delivery dates.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Supplier Rating</strong>: Rate and review suppliers based on their performance and reliability.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Order and Sales Management:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Sales Tracking</strong>: Monitor sales and track the movement of products. Sales data is automatically updated in inventory to reflect accurate stock counts.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Purchase Orders</strong>: Create purchase orders to replenish stock levels. The app can suggest reordering based on stock levels and reorder points set for each product.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Invoice Generation</strong>: Automatically generate invoices for sales and purchase transactions, which can be emailed to customers or suppliers.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Order History</strong>: Keep a detailed history of all orders placed, including order date, product, quantity, price, and supplier/customer.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Inventory Alerts and Notifications:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Low Stock Alerts</strong>: Automated alerts when inventory levels fall below the predefined threshold for reordering.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Expiry Dates</strong>: For perishable products, the app tracks expiration dates and sends reminders to help with timely sales or disposal.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Reports &amp; Analytics:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Sales Reports</strong>: Generate reports on sales performance, including total sales, best-selling products, and profit margins.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Stock Reports</strong>: View reports on current inventory levels, reorder trends, and product performance.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Supplier Reports</strong>: Track supplier performance in terms of delivery times, order accuracy, and overall reliability.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>User Role Management:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Admin Role</strong>: Full access to manage products, suppliers, orders, and users.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Sales Role</strong>: Limited access to view and manage orders, sales, and customer interactions.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Supplier Role</strong>: Suppliers can access their specific product list, view orders, and update delivery status.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Multi-location Support (Optional):</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>If Sanjog Suppliers operates in multiple warehouses or stores, the app can support inventory management across multiple locations, helping track stock availability per location.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Dashboard:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>A real-time dashboard provides an overview of the current status, including stock levels, orders, pending deliveries, and sales trends. This dashboard helps users quickly understand the status of the inventory and make informed decisions.</li></ol><h3><strong>Technology Stack:</strong></h3><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Frontend (UI/UX):</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>React</strong> or <strong>Angular</strong> for building a dynamic and responsive user interface.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Redux</strong> for state management (especially for handling inventory and sales data across components).</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Bootstrap</strong> or <strong>Material UI</strong> for fast and responsive design components.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Backend (Server-side):</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Node.js</strong> with <strong>Express.js</strong> for handling API requests and business logic.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>MongoDB</strong> or <strong>MySQL</strong> for database management. MongoDB could be suitable for flexible product data, while MySQL might work well for structured transactional data.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>JWT (JSON Web Tokens)</strong> for secure authentication and authorization.</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Authentication &amp; Security:</strong></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span>User authentication can be handled with <strong>OAuth</strong> or <strong>JWT</strong> to ensure secure login for admins, staff, and suppliers.</li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Role-based access control (RBAC)</strong> to limit access to specific sections of the app based on user roles.</li></ol><h3><br></h3><p><br></p>','http://localhost:8000/uploads/projects/2026/08/20260801075323_paste-1785570761937.png',1,NULL,NULL,'c23dfce1-449f-4cb3-be5e-b4fa82e6','2026-08-01 13:38:24','b7dbe8ee-6aac-48da-b054-58d15a3c','093b11b5-3d58-4c2a-9aab-44232eb7'),('TikTak Project Using C','academicsproject','<p><span style=\"background-color: oklch(0.928 0.006 264.531); color: rgb(0, 0, 0);\">My 1st semester project (Tiktactoe) C language, a simple application has been prepared. The Tic-tac-toe is a pencil game for two players, X and O, who takes turns marking the spaces in a 3X3 grid player.</span></p>','<p><strong style=\"color: rgb(0, 0, 0);\">Tic-Tac-Toe</strong><span style=\"color: rgb(0, 0, 0);\"> is a simple console-based game developed in </span><strong style=\"color: rgb(0, 0, 0);\">C</strong><span style=\"color: rgb(0, 0, 0);\"> as my </span><strong style=\"color: rgb(0, 0, 0);\">first-semester project</strong><span style=\"color: rgb(0, 0, 0);\">. The application implements the classic two-player Tic-Tac-Toe game, where players take turns placing </span><strong style=\"color: rgb(0, 0, 0);\">X</strong><span style=\"color: rgb(0, 0, 0);\"> and </span><strong style=\"color: rgb(0, 0, 0);\">O</strong><span style=\"color: rgb(0, 0, 0);\"> on a </span><strong style=\"color: rgb(0, 0, 0);\">3×3 grid</strong><span style=\"color: rgb(0, 0, 0);\">. The objective is to align three identical symbols horizontally, vertically, or diagonally before the opponent.</span></p><h2><span style=\"color: rgb(0, 0, 0);\">Key Features</span></h2><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Two-player gameplay in the command-line interface</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Interactive 3×3 game board</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Turn-based player input with alternating X and O</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Automatic detection of winning combinations</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Draw detection when all cells are filled without a winner</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Input validation to prevent overwriting occupied cells</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Simple and user-friendly console interface</span></li></ol><h2><span style=\"color: rgb(0, 0, 0);\">Technologies Used</span></h2><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">C Programming Language</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Standard C Library</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Console-based Input/Output</span></li></ol><h2><span style=\"color: rgb(0, 0, 0);\">Learning Outcomes</span></h2><p><span style=\"color: rgb(0, 0, 0);\">This project strengthened my understanding of fundamental programming concepts, including variables, loops, conditional statements, functions, arrays, and basic game logic. It also helped me develop problem-solving skills by implementing input validation, win-condition checking, and overall game flow in a structured manner.</span></p><p><br></p>','/uploads/projects/2026/08/20260801090534_paste-1785575106212.png',1,NULL,NULL,NULL,'2026-08-01 14:50:34','bbcf5066-02ef-4839-8e00-f4f5406f','4bb907d2-abc7-4e2f-9971-5a3db5bd'),('Ward Darta Chalani','workproject','<p>The Ward Darta System consists of two main components: a desktop application (Darta UI) and a backend service (Chalani Darta Backend).</p>','<h3><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Darta UI (Desktop Application)</strong></h3><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Technologies:</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Electron.js</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: A framework that allows the creation of cross-platform desktop applications using web technologies such as HTML, CSS, and JavaScript. Electron provides access to native system features and is used here to create a desktop UI for interacting with ward documents and reports.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">React.js</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: A JavaScript library used for building the user interface, ensuring a responsive and modern design.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Material-UI</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: A React component library for building sleek and functional UIs.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">TypeScript</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Used to ensure type safety throughout the application.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Redux</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: State management to handle the application state across various UI components.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">i18next</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: A library used for internationalization, enabling the app to support multiple languages.</span></li></ol><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Functionality:</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Report Viewing</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: The desktop application allows users to view reports generated by the backend. Reports can include ward data, medical records, and other relevant documents.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Report Generation for Print</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Users can generate reports in formats suitable for printing, such as PDF or Word documents. The desktop app provides a clean interface for the user to generate these reports on-demand.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Document Access</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Users can access and interact with files stored in the system, which could include Word documents or PDFs, and perform tasks like viewing or printing.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Networked File Access via Samba</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: The desktop app allows users to open documents from a </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Samba share</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">, ensuring they can access files located on a remote network file system. The app can open files, such as Word documents, from shared directories on the network.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Electron Integration</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: The desktop application integrates with Electron\'s capabilities to interact with the local file system and external resources.</span></li></ol><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Building &amp; Packaging:</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The app can be packaged for multiple platforms (Windows, macOS, and Linux) using </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">electron-builder</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">. It generates native installation packages for each operating system.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The app is designed for easy installation and can create desktop and start menu shortcuts, with a customized installer and license agreement.</span></li></ol><h3><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Chalani Darta Backend</strong></h3><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Technologies:</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Node.js</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> with </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Express.js</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: The backend service is built on Node.js, using the Express.js framework to handle HTTP requests.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">TypeScript</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Ensures type safety and improves code quality.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Sequelize ORM</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Manages interactions with the PostgreSQL database, storing ward-related data.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">JWT Authentication</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Uses JSON Web Tokens for secure authentication of users.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Bcryptjs</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Encrypts user passwords for secure storage.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Joi &amp; Yup</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Libraries used for input validation and schema validation.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Multer</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Manages file uploads, allowing users to upload documents to the server.</span></li></ol><p><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Functionality:</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Report Generation</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: The backend handles the creation of reports, including interacting with databases and generating downloadable files in formats like CSV or Word. The generated reports can be fetched by the frontend (Darta UI) for viewing or printing.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Database Management</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: The backend interacts with a PostgreSQL database to store and retrieve ward-related data, such as medical records, personnel details, and report logs.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">File Handling</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: The backend also allows for file uploads and management, using </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Multer</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> to handle file uploads (such as Word or PDF reports) from users. Additionally, it can read and export files, making it easy for the frontend to fetch and display them.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Network File Management</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Integrates with Samba shares to facilitate file retrieval from networked drives. This allows users to access and open files (such as Word documents) stored in remote shared directories over the network.</span></li></ol><h3><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Features &amp; Workflow:</strong></h3><ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">User Authentication</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">: Users log into the system via JWT authentication. Once authenticated, they can interact with the backend to generate reports, access documents, and perform various tasks.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Generate Reports</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">:</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Users can trigger report generation on the backend via API calls.</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Reports can be customized and generated based on specific criteria (e.g., ward statistics, patient data, etc.).</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Once generated, reports are available for viewing or downloading by the user.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Document Interaction</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">:</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The desktop application allows the user to open, view, and print documents stored locally or on network shares.</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Documents such as Word files (using Samba share) can be opened directly from the network location, enabling seamless access to remote documents.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Samba File Access</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">:</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The desktop app connects to networked directories via </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Samba</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">, allowing users to open Word documents or other files directly from shared folders.</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">This is particularly useful for collaborative environments where files are stored on a central server, and multiple users need access to the same documents.</span></li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Export &amp; Print</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">:</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Users can export generated reports in printable formats like </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">Word</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\"> or </span><strong style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">PDF</strong><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">.</span></li><li data-list=\"bullet\" class=\"ql-indent-1\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"background-color: rgb(255, 255, 255); color: rgb(0, 0, 0);\">The backend handles the creation of the documents, and the frontend provides a user-friendly interface to view and print them.</span></li></ol><p><br></p>','http://localhost:8000/uploads/projects/2026/08/20260801080230_paste-1785571191572.png',1,NULL,NULL,'0b83aff6-3bb2-43df-ab0c-0bc39a7a','2026-08-01 13:47:30','bf5782f5-8f35-4904-905a-a3cb6277','fe2b2739-1f4c-48af-80ca-31edbe3d'),('Nerd Study Hub','workproject','<p>All Tech and Engineering Solution in one</p>','<h1><span style=\"color: rgb(0, 0, 0);\">NerdStudyHub – Online Learning Platform</span></h1><p><strong style=\"color: rgb(0, 0, 0);\">NerdStudyHub</strong><span style=\"color: rgb(0, 0, 0);\"> is a role-based e-learning platform built for students preparing for </span><strong style=\"color: rgb(0, 0, 0);\">MCC Entrance, ICE Entrance, BCA Entrance, and Engineering Council License Exams</strong><span style=\"color: rgb(0, 0, 0);\">. The platform provides subject-wise notes, mock exams, and real-time communication between students and teachers. It is developed using </span><strong style=\"color: rgb(0, 0, 0);\">React</strong><span style=\"color: rgb(0, 0, 0);\"> for the frontend and </span><strong style=\"color: rgb(0, 0, 0);\">Node.js, Express.js, and PostgreSQL</strong><span style=\"color: rgb(0, 0, 0);\"> for the backend.</span></p><h2><span style=\"color: rgb(0, 0, 0);\">Frontend (React)</span></h2><p><span style=\"color: rgb(0, 0, 0);\">The frontend is built with React, providing a responsive and user-friendly interface for students, teachers, and administrators.</span></p><p><strong style=\"color: rgb(0, 0, 0);\">Key Features:</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Role-Based Authentication (Admin, Teacher, Student)</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Student dashboard with notes, mock exams, and progress</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Teacher dashboard for managing assigned subjects and uploading notes</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Admin dashboard for user and subject management</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Real-time chat between students and teachers using Socket.IO</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Responsive design for desktop and mobile</span></li></ol><p><strong style=\"color: rgb(0, 0, 0);\">Key Technologies:</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">React</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">React Router</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Axios</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Socket.IO Client</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">JWT Authentication</span></li></ol><h2><span style=\"color: rgb(0, 0, 0);\">Backend (Node.js, PostgreSQL)</span></h2><p><span style=\"color: rgb(0, 0, 0);\">The backend is powered by Node.js and Express.js with PostgreSQL and Sequelize ORM for secure and scalable data management.</span></p><p><strong style=\"color: rgb(0, 0, 0);\">Key Features:</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">JWT-based authentication with RBAC</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Admin can assign subjects to teachers</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Teachers can upload and manage subject notes</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Students can access learning materials and interact with teachers</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Mock exam management and result tracking</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Admin dashboard to monitor teacher activities and platform usage</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Secure REST APIs and real-time communication using Socket.IO</span></li></ol><p><strong style=\"color: rgb(0, 0, 0);\">Key Technologies:</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Node.js</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Express.js</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">PostgreSQL</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Sequelize ORM</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">JWT</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Socket.IO</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">bcrypt</span></li></ol><h3><span style=\"color: rgb(0, 0, 0);\">Deployment</span></h3><p><strong style=\"color: rgb(0, 0, 0);\">Website:</strong><span style=\"color: rgb(0, 0, 0);\"> </span><a href=\"https://nerdstudyhub.com/\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(0, 0, 0);\">https://nerdstudyhub.com</a></p><p><span style=\"color: rgb(0, 0, 0);\">The platform offers a complete online learning solution with secure role-based access, study materials, mock examinations, and real-time teacher-student interaction.</span></p><p><br></p>','http://localhost:8000/uploads/projects/2026/08/20260801081049_paste-1785571732355.png',1,NULL,NULL,'56b14114-b7a1-43f4-aef8-46a4e3f8','2026-08-01 13:55:49','efae7d74-bb3f-43a6-9c26-9ae9755b','9a2563fd-f8be-41fa-bf27-3e170153'),('Density Based Traffic Light','workproject','<p><span style=\"background-color: oklch(0.928 0.006 264.531); color: rgb(0, 0, 0);\">Density Based Automatic Traffic Light Controlled System that helps to control traffics and reduces accidents.</span></p>','<p><strong style=\"color: rgb(0, 0, 0);\">Density-Based Automatic Traffic Light Control System</strong><span style=\"color: rgb(0, 0, 0);\"> is an intelligent traffic management project developed to improve traffic flow and reduce congestion at road intersections. Unlike traditional traffic signals that operate on fixed time intervals, this system adjusts the traffic light duration based on the density of vehicles detected on each road, resulting in more efficient traffic control and reduced waiting time.</span></p><h2><span style=\"color: rgb(0, 0, 0);\">Key Features</span></h2><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Automatic traffic light control based on vehicle density</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Dynamic signal timing to reduce traffic congestion</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Prioritizes roads with higher traffic volume</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Helps minimize unnecessary waiting time at intersections</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Improves overall traffic efficiency and road safety</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Reduces fuel consumption and vehicle emissions caused by long idle times</span></li></ol><h2><span style=\"color: rgb(0, 0, 0);\">Technologies Used</span></h2><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Embedded System / Microcontroller</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Traffic Density Sensors</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">C/C++ Programming</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(0, 0, 0);\">Electronic Components (LEDs, Sensors, Signal Modules)</span></li></ol><h2><span style=\"color: rgb(0, 0, 0);\">Learning Outcomes</span></h2><p><span style=\"color: rgb(0, 0, 0);\">This project enhanced my understanding of embedded systems, sensor integration, traffic automation, and real-time decision-making. It provided practical experience in developing an intelligent traffic control solution that optimizes signal timing based on real-world traffic conditions, contributing to smarter and safer transportation systems.</span></p><p><br></p>','http://localhost:8000/uploads/projects/2026/08/20260801090814_paste-1785575271818.png',1,NULL,NULL,NULL,'2026-08-01 14:53:14','f05b15eb-9425-4f27-b097-a4cc1d04','c6cb0e3a-9310-414b-aa16-b531ad99');
